entries[86861] = { ["name"] = "Erdbeben", ["text"] = "35 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nIhr lasst die Erde an einem ausgewählten Zielort beben und brechen, wodurch Feinde in einem Umkreis von 8 Metern alle 1 Sek. Naturschaden erleiden. Hält 10 Sek. lang an." }
