entries[86864] = { ["name"] = "Tönerne Urne", ["text"] = "Wirken in 2 sek. 5\nEinige Zwerge beerdigten ihre Verstorbenen in Gräbern. Jene, welche sich wegen Untoten beunruhigten, mögen eher den Weg der Einäscherung gewählt haben. Diese Urne ist angeschlagen und gesprungen, die Asche längst in alle Winde verstreut. Auf der Unterseite ist in zwergischen Runen das Wort 'Donnerblitz' zu erkennen.\nTönerne Urne\nWird beim Aufheben gebunden" }
entries[86865] = { ["name"] = "Abgenutztes Jagdmesser", ["text"] = "Wirken in 2 sek. 5\nDie Klinge dieser Waffe ist schartig und ihr Griff besteht aus einem Elch- oder Widderhorn. Nahe dem Knauf sind die Initialien 'W. G.' eingeschnitzt.\nAbgenutztes Jagdmesser\nWird beim Aufheben gebunden" }
entries[86866] = { ["name"] = "Knöcherne Würfel", ["text"] = "Wirken in 2 sek. 5\nZwerge lieben Gold so sehr, wie sie auch das Trinken lieben. Ergo war das Glücksspiel die logische Folge. Diese Würfel scheinen aus Schafsknochen geschnitzt worden zu sein. In den Würfelaugen hat sich ein wenig verkrustetes Blut festgesetzt.\nKnöcherne Würfel\nWird beim Aufheben gebunden" }
